// Certificate of insurance, generated by LitePAS (the policy system), separate from Spark's quote documents.
import { PDFDocument, StandardFonts, rgb } from 'pdf-lib';
import { BRANDS, productName } from './format';

const hex = (h) => { const n = parseInt(h.replace('#', ''), 16); return rgb(((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255); };
const money = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v)) ? '-' : 'KES ' + Number(v).toLocaleString('en-KE', { maximumFractionDigits: 0 }));
const per = (plan) => ({ 'Annual': 'a year', 'Semi-Annual': 'every 6 months', 'Quarterly': 'a quarter', 'Monthly': 'a month', 'Weekly (Mobile)': 'a week', 'Flexi Top-Up (Mobile)': 'a week' }[plan] || '');
const ascii = (s) => String(s ?? '-').replace(/[^\x20-\x7E]/g, '-');

export async function certificatePdf(p) {
  const doc = await PDFDocument.create();
  doc.setTitle(`Certificate of insurance ${p.policyNumber}`); doc.setAuthor('LitePAS for ICEA LION');
  const page = doc.addPage([595.28, 841.89]); const { width, height } = page.getSize();
  const font = await doc.embedFont(StandardFonts.Helvetica); const bold = await doc.embedFont(StandardFonts.HelveticaBold);
  const brand = BRANDS[p.journey] || BRANDS.direct; const C = hex(brand.color); const INK = hex('#0F1E33'); const MUTED = hex('#566781'); const LINE = hex('#DCE3EC');
  const q = p.quote || {}; const b = p.benefits || {}; const M = 48; let y = height - 40;
  const text = (s, x, yy, o = {}) => page.drawText(ascii(s), { x, y: yy, size: o.size || 10, font: o.bold ? bold : font, color: o.color || INK });
  const right = (s, x, yy, o = {}) => { const f = o.bold ? bold : font; const sz = o.size || 10; text(s, x - f.widthOfTextAtSize(ascii(s), sz), yy, o); };

  page.drawRectangle({ x: 0, y: height - 92, width, height: 92, color: C });
  text(brand.name, M, height - 44, { size: 18, bold: true, color: rgb(1, 1, 1) });
  text(p.journey === 'direct' ? 'Jamii Protect, sold direct' : `Jamii Protect through ${brand.name}`, M, height - 62, { size: 10, color: rgb(1, 1, 1) });
  right('CERTIFICATE OF INSURANCE', width - M, height - 44, { size: 12, bold: true, color: rgb(1, 1, 1) });
  right(p.policyNumber, width - M, height - 62, { size: 11, color: rgb(1, 1, 1) });
  y = height - 128;

  const section = (t) => { text(t.toUpperCase(), M, y, { size: 8.5, bold: true, color: C }); y -= 6; page.drawLine({ start: { x: M, y }, end: { x: width - M, y }, thickness: 0.8, color: LINE }); y -= 16; };
  const row = (k, v) => { text(k, M, y, { color: MUTED }); text(v, M + 190, y, { bold: true }); y -= 17; };

  section('Policy');
  row('Policyholder', p.customer?.name); row('Customer reference', p.customer?.reference);
  row('Product', `${productName(q.product)} (${q.product || '-'})`); row('Status', p.status);
  row('Cover starts', q.coverStart); row('Renewal date', q.renewal);
  row('Insurers', 'ICEA LION Life and ICEA LION General');
  y -= 6; section('Premium');
  row('Payment plan', `${q.plan} by ${q.method}`); row('Instalment', `${money(q.instalment)} ${per(q.plan)}`);
  row('First instalment', `${money(q.firstInstalment)} including stamp duty`); row('Annual premium', money(q.annualPremium));
  y -= 6; section('Cover');
  const lines = [['Life cover, policyholder', b.Principal_Death_Benefit], Number(b.Spouse_Benefit) > 0 && ['Life cover, spouse', b.Spouse_Benefit],
    Number(b.Children_Covered) > 0 && [`Life cover, each child (${b.Children_Covered})`, b.Child_Benefit], Number(b.Parents_Covered) > 0 && [`Last expense, each parent (${b.Parents_Covered})`, b.Parent_Benefit],
    Number(b.PA_Accidental_Death) > 0 && ['Accidental death, additional', b.PA_Accidental_Death], Number(b.HC_Daily) > 0 && ['Hospital cash, per night', b.HC_Daily]].filter(Boolean);
  for (const [k, v] of lines) { text(k, M, y, { color: MUTED }); right(money(v), width - M, y, { bold: true }); y -= 17; }
  y -= 6; section('Rating basis');
  row('Versions priced on', `Product ${q.productVersion || '-'}, Rating ${q.ratingVersion || '-'}, Quote ${q.quoteVersion || '-'}`);
  row('Priced as of', q.asOf ? new Date(q.asOf).toISOString().replace('T', ' ').slice(0, 19) + ' UTC' : '-');
  row('Quote reference', `${q.reference || '-'} revision ${q.revision || '-'}`); row('Spark call', q.sparkCallId || '-');
  row('Sold through', `${p.partnerLabel || brand.name} (${p.channel})`);
  y -= 10;
  const notes = ['Benefits are subject to the waiting periods and exclusions in the policy schedule.', 'This certificate is issued by the policy administration system from the accepted quote; the quote and benefit',
    'illustration documents were produced by the ICEA LION quotation service.', 'Illustrative values for the ICEA LION Product Builder POC. Not an offer of insurance.'];
  for (const n of notes) { text(n, M, y, { size: 8.5, color: MUTED }); y -= 12; }
  page.drawLine({ start: { x: M, y: 60 }, end: { x: width - M, y: 60 }, thickness: 0.8, color: LINE });
  text(`Issued by LitePAS on ${new Date(p.createdAt).toISOString().slice(0, 10)}`, M, 44, { size: 8.5, color: MUTED });
  right(`${p.policyNumber}  |  ${p.crm?.reference || ''}`, width - M, 44, { size: 8.5, color: MUTED });
  return doc.save();
}
